    # --- Archaeological restrictions ---
    parts.append("\n=== ARCHAEOLOGICAL RESTRICTIONS ===")
    arch_poleo = all_layers.get("arch_zone_poleo", [])
    arch_keys = [k for k in all_layers if k.startswith("arch_")]
