/* ========================================================================
   ZONING TAB
   ======================================================================== */
let zoningMap = null;

// Store resolved coords from KAEK lookup
let zoningCoords = { lat: null, lon: null, x: null, y: null, area_m2: null };

function doKaekLookup() {
  let kaek = document.getElementById('zoning-kaek').value.trim();
  // Strip KAEK prefix
  kaek = kaek.replace(/^KAEK\s*/i, '').replace(/^ΚΑΕΚ\s*/i, '').trim();
  if (!kaek) return;

  document.getElementById('zoning-spinner').classList.add('active');
  document.getElementById('zoning-results').style.display = 'none';

  fetch('/api/v1/zoning/kaek', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ kaek }),
  })
  .then(r => r.json())
  .then(data => {
    if (!data.found) {
      showToast(t('kaek_not_found'));
      document.getElementById('zoning-spinner').classList.remove('active');
      return;
    }
    // Store resolved coordinates
    zoningCoords = {
      lat: data.lat, lon: data.lon,
      x: data.x, y: data.y,
      area_m2: data.area_m2 || null,
    };
    showToast('KAEK ' + kaek + ' — ' + t('running_check'));
    // Auto-run zoning check
    doZoningCheck();
  })
  .catch(() => {
    showToast(t('kaek_not_found'));
    document.getElementById('zoning-spinner').classList.remove('active');
  });
}

function doZoningCheck() {
  if (zoningCoords.lat == null || zoningCoords.lon == null) {
    showToast(t('no_coords'));
    document.getElementById('zoning-spinner').classList.remove('active');
    return;
  }

  const body = {
    coord_system: 'wgs84',
    lat: zoningCoords.lat,
    lon: zoningCoords.lon,
    intended_use: 'residential',
    area_m2: zoningCoords.area_m2,
  };

  document.getElementById('zoning-spinner').classList.add('active');
  document.getElementById('zoning-results').style.display = 'none';

  fetch('/api/v1/zoning/check', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  .then(r => r.json())
  .then(renderZoningResults)
  .catch(err => { showToast('Error: ' + err.message); })
  .finally(() => { document.getElementById('zoning-spinner').classList.remove('active'); });
}

function renderZoningResults(data) {
  // Verdict card
  const vEmoji = data.verdict === 'green' ? '\u2705' : data.verdict === 'yellow' ? '\u26A0\uFE0F' : '\u274C';
  document.getElementById('zoning-verdict-card').innerHTML =
    `<div class="verdict-card verdict-${data.verdict}">${vEmoji} ${escapeHtml(data.verdict_summary)}</div>`;

  // Meta grid
  const kaekVal = document.getElementById('zoning-kaek').value.trim().replace(/^KAEK\s*/i, '').replace(/^ΚΑΕΚ\s*/i, '');
  const coordsStr = zoningCoords.x != null ? `${zoningCoords.x.toFixed(2)}, ${zoningCoords.y.toFixed(2)}` : zoningCoords.lat != null ? `${zoningCoords.lat.toFixed(6)}, ${zoningCoords.lon.toFixed(6)}` : '-';
  document.getElementById('zoning-meta').innerHTML = `
    <div class="meta-item"><label>KAEK</label><div class="meta-value">${escapeHtml(kaekVal || '-')}</div></div>
    <div class="meta-item"><label>EGSA87</label><div class="meta-value">${coordsStr}</div></div>
    <div class="meta-item"><label>${t('zone_label')}</label><div class="meta-value">${escapeHtml(data.zone_name || '-')}</div></div>
    <div class="meta-item"><label>${t('land_use_label')}</label><div class="meta-value">${escapeHtml(data.land_use || '-')}</div></div>
    <div class="meta-item"><label>${t('municipality_label')}</label><div class="meta-value">${escapeHtml(data.municipality || '-')}</div></div>
    ${zoningCoords.area_m2 ? '<div class="meta-item"><label>' + t('plot_area') + '</label><div class="meta-value">' + zoningCoords.area_m2.toFixed(2) + ' m\u00B2</div></div>' : ''}
  `;

  // Risk flags
  let flagsHtml = '';
  (data.risk_flags || []).forEach(f => {
    flagsHtml += `<div class="risk-flag">
      <div class="risk-flag-header">
        <span class="risk-badge ${f.level}">${f.level.toUpperCase()}</span>
        <strong>${escapeHtml(f.title)}</strong>
      </div>
      <div style="font-size:13px;color:var(--muted);">${escapeHtml(f.description)}</div>
    </div>`;
  });
  document.getElementById('zoning-risk-flags').innerHTML = flagsHtml;

  // Building params
  const bp = data.building_params || {};
  const pv = (v, suffix) => v != null ? v + (suffix || '') : '-';
  document.getElementById('zoning-params').innerHTML = `
    <div class="param-item"><label>${t('coverage_label')}</label><div class="param-value">${pv(bp.coverage_ratio)}</div></div>
    <div class="param-item"><label>${t('factor_label')}</label><div class="param-value">${pv(bp.building_factor)}</div></div>
    <div class="param-item"><label>${t('height_label')}</label><div class="param-value">${pv(bp.max_height_m, 'm')}</div></div>
    <div class="param-item"><label>${t('floors_label')}</label><div class="param-value">${pv(bp.max_floors)}</div></div>
    <div class="param-item"><label>${t('min_lot_label')}</label><div class="param-value">${pv(bp.min_lot_size_m2, ' m\u00B2')}</div></div>
    <div class="param-item"><label>${t('frontage_label')}</label><div class="param-value">${pv(bp.min_frontage_m, 'm')}</div></div>
    <div class="param-item"><label>${t('building_sys_label')}</label><div class="param-value">${pv(bp.building_system)}</div></div>
    <div class="param-item"><label>${t('fek_label')}</label><div class="param-value">${bp.fek_url ? escapeHtml(bp.fek || '') + ' <a class="fek-link" href="' + escapeHtml(bp.fek_url) + '" target="_blank" rel="noopener noreferrer">&#128196; PDF</a>' : pv(bp.fek)}</div></div>
  `;

  // Data source & disclaimer
  document.getElementById('zoning-data-source').textContent = data.data_source || '';
  document.getElementById('zoning-disclaimer').textContent = data.disclaimer || '';

  // Show results first so map container is visible, then render map
  document.getElementById('zoning-results').style.display = '';
  setTimeout(() => renderZoningMap(data), 50);
}

function renderZoningMap(data) {
  const lat = zoningCoords.lat;
  const lon = zoningCoords.lon;
  if (lat == null || lon == null) return;

  const container = document.getElementById('zoning-map');
  if (zoningMap) { zoningMap.remove(); zoningMap = null; }
  zoningMap = L.map(container).setView([lat, lon], 16);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; OpenStreetMap', maxZoom: 19
  }).addTo(zoningMap);

  const colors = { green: '#22c55e', yellow: '#eab308', red: '#ef4444' };
  const color = colors[data.verdict] || '#2563eb';

  L.circleMarker([lat, lon], { radius: 8, color, fillColor: color, fillOpacity: 0.8, weight: 2 }).addTo(zoningMap);
  L.circle([lat, lon], { radius: 100, color, fillOpacity: 0.08, weight: 1 }).addTo(zoningMap);

  zoningMap.invalidateSize();
  reverseGeocode(lat, lon, 'zoning-address');
}

/* ========================================================================
   REPORT TAB
   ======================================================================== */
let reportMap = null;

